import { spawnSync } from 'node:child_process';

export const DATASET_EXECUTABLE_NAME = 'test20_executable';

const DATASET_EXECUTABLE_PATH = '/workspace/dataset/test20_executable';

export function runExecutable(args) {
  const completed = spawnSync(DATASET_EXECUTABLE_PATH, args, {
    encoding: 'utf8',
    maxBuffer: 16 * 1024 * 1024,
  });

  if (completed.error) {
    throw completed.error;
  }

  return {
    status: completed.status === null ? 1 : completed.status,
    stdout: completed.stdout || '',
    stderr: completed.stderr || '',
  };
}

